                      </label>
                      <label>
                        다음 종료일
                        <input
                          required
                          type="date"
                          min={modal.next_start}
                          value={modal.next_end}
                          onChange={(e) => field("next_end", e.target.value)}
                        />
                      </label>
                    </div>
                  </>
                )}
                <div className="form-footer">
                  {modal.kind === "task" &&
                    data.tasks.some((t) => t.id === modal.id) && (
                      <button
                        type="button"
                        className="danger"
                        disabled={busy}
                        onClick={() => {
                          if (
                            confirm(
                              "이 할 일을 삭제할까요? 실행 기록은 내보내기에 보존됩니다.",
