                  <button className="primary" disabled={busy} type="submit">
                    {busy
                      ? "저장 중…"
                      : modal.kind === "review"
                        ? "저장하고 다음 계획 만들기"
                        : "저장하기"}
                  </button>
                </div>
              </form>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

