export function dailySummary(days) {
  const group = (rows) => ({
    count: rows.length,
    total: rows.reduce((n, r) => n + r.minutes, 0),
    average: rows.length
      ? Math.round(
          (rows.reduce((n, r) => n + r.minutes, 0) / rows.length) * 10,
        ) / 10
      : null,
  });
  return {
    all: group(days),
    before: group(days.filter((d) => d.day_index <= 2)),
    after: group(days.filter((d) => d.day_index >= 3)),
  };
}

